// Messages from anyone except the owner's chat are dropped without a reply.
const m = $json.message;
if (!m || String(m.chat?.id) !== '__CHAT_ID__') return [];
const cmd = String(m.text || '').trim().split(/\s+/)[0].split('@')[0].toLowerCase();
return [{ json: { cmd } }];

const n = $('Site numbers').first().json;
const st = $('Parse backup status').first().json?.data || null;
const site = $('Site check').first().json || {};
const tz = 'Asia/Kolkata';
const today = new Date().toLocaleDateString('en-CA', { timeZone: tz });
const daysOld = (d) => d ? Math.floor((Date.parse(today) - Date.parse(String(d).slice(0, 10))) / 86400000) : null;
const fmt = (d, o) => new Date(d).toLocaleString('en-IN', { timeZone: tz, ...o });
const problems = [];

const code = Number(site.statusCode) || 0;
const siteLine = code === 200 ? 'up' : 'NOT OK (' + (code ? 'HTTP ' + code : (site.error?.message || 'no response')) + ')';
if (code !== 200) problems.push('Website check failed');

let backupLine = 'none found';
if (st && st.ok) {
  const h = Math.round((Date.now() - Date.parse(st.created_at)) / 3600000);
  backupLine = h + ' h ago, ' + (st.size / 1048576).toFixed(2) + ' MB';
  if (h >= 8) problems.push('Last backup is ' + h + ' hours old');
} else problems.push('No successful backup recorded');

const gAge = daysOld(n.gold_date);
if (gAge === null || gAge > 0) problems.push('Gold and silver prices were not updated today');
const fAge = daysOld(n.fuel_as_of);
if (fAge !== null && fAge > 14) problems.push('Fuel data is ' + fAge + ' days old (update src/lib/fuel-data.ts or add an admin override)');
const lAge = daysOld(n.lpg_as_of);
if (lAge !== null && lAge > 40) problems.push('LPG data is ' + lAge + ' days old');

const head = problems.length ? 'NEEDS ATTENTION:\n- ' + problems.join('\n- ') : 'Everything looks fine.';
const lines = [
  'Paisa Reality report, ' + fmt(Date.now(), { day: 'numeric', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) + ' IST',
  '',
  head,
  '',
  'Website: ' + siteLine,
  'Last backup: ' + backupLine,
  'Gold and silver: ' + (n.gold_written_at ? 'updated ' + fmt(n.gold_written_at, { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : 'no data'),
  'Fuel verified: ' + (n.fuel_as_of || 'no data') + ', LPG verified: ' + (n.lpg_as_of || 'no data'),
  '',
  'Users: ' + n.users + ' (+' + n.users_24h + ' in 24 h)',
  'Newsletter subscribers: ' + n.subscribers + ' (+' + n.subscribers_24h + ' in 24 h)',
  'Active price alerts: ' + n.active_alerts,
  'Contact messages: ' + n.messages_24h + ' in 24 h, ' + n.messages_unread + ' unread',
  'Articles published: ' + n.articles + ', schemes live: ' + n.schemes,
];
return [{ json: { text: lines.join('\n') } }];

const r = $json;
const fix = (r.issues || []).filter((i) => i.level === 'fix');
const review = (r.issues || []).filter((i) => i.level === 'review');
if (false && fix.length === 0 && review.length === 0) return [];
const lines = ['Data health, ' + new Date().toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', day: 'numeric', month: 'short' })];
if (!fix.length && !review.length) lines.push('', 'Everything is current: prices, rates, deadlines and official links.');
if (fix.length) lines.push('', 'Fix now:', ...fix.map((i) => '- ' + i.text));
if (review.length) lines.push('', 'Review:', ...review.map((i) => '- ' + i.text));
const p = r.facts?.latestPrice || {};
lines.push('', 'Latest prices: gold ' + p.gold + ', fuel ' + p.fuel + ', LPG ' + p.lpg);
return [{ json: { text: lines.join('\n').slice(0, 3900) } }];

const r = $json;
const text = r.skipped ? 'Not sent: ' + r.skipped + '.' : 'Weekly post emailed: ' + r.sent + ' sent, ' + r.failed + ' failed, of ' + r.total + ' subscribers.';
return [{ json: { text } }];
